import {research,partnerVision,PARTNER_VISION} from './presentation.mjs';
import {presentation,portalPage,journeyOnboarding} from './showcase.mjs';
import {JOURNEYS,REVIEW_STORAGE_KEY,emptyReview,addReviewPerson,REVIEW_MATERIALS,ONBOARDING_STEPS,ROLE_PATHS} from './journey.config.mjs';
import {carePanel,weeklyCharts,budgetPanel,DAY_MODES} from './care.mjs';
import {PRODUCT,PLANS,AFFILIATE_POLICY} from './product.config.mjs';
import {creatorPortal,CREATOR_MATERIALS} from './creator.mjs';
import {rhythmPage,RITUAL_PRESETS} from './rhythm.mjs';
import {CONVERSATION_STYLES} from './conversation.config.mjs';
import {ecosystem} from './ecosystem.mjs';
import {launchPage,LAUNCH_DATA} from './launch.mjs';
import {uid,normalize,localDay,emptyState,parseCapture,queryMemory,dailyStats,dateTimeToISO,TIMEZONES,TIMEZONE_CONFIG} from './logic.mjs';
import {icon,e,flower,brand,nav} from './ui.mjs';
import {designSystem} from './design-system.mjs';
const root=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const money=(n,c='BRL')=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:c}).format(n);
const DEFAULT_TIMEZONE='America/Sao_Paulo';
const timezone=()=>state.settings.timezone||DEFAULT_TIMEZONE;
const currentDay=()=>localDay(new Date(),timezone());
const dateAtNoon=(date,zone=timezone())=>dateTimeToISO(date,'12:00',zone);
const fmt=(d,options={day:'2-digit',month:'short'},zone=timezone())=>d?new Intl.DateTimeFormat('pt-BR',{timeZone:zone,...options}).format(new Date(d)):'';
const timezoneLabels=TIMEZONE_CONFIG;
const timezoneChoices=TIMEZONES.map(value=>[value,timezoneLabels[value]]);
const timezoneField=(selected=timezone(),id="workspace-timezone")=>`<label for="${id}">Fuso dos seus compromissos</label><select id="${id}" name="timezone">${timezoneChoices.map(([value,label])=>`<option value="${value}" ${value===selected?'selected':''}>${label}</option>`).join('')}</select><p class="record-note">${id==='task-timezone'?'Horários deste compromisso usam esse fuso. Ao alterá-lo, confira data e horário.':'Novos registros usam esse fuso. Compromissos já salvos mantêm o horário original.'}</p>`;
const nowDate=()=>new Intl.DateTimeFormat('pt-BR',{timeZone:timezone(),weekday:'long',day:'numeric',month:'long'}).format(new Date());
let state=emptyState(),realState=null,etag=null,view='presentation',demo=false,busy=false,status={},filter='all',search='',pending=[],dialogAction=null,voice=null,menuOpen=false,menuReturnFocus=null,dialogReturnFocus=null;
const routineNotified=new Set(),closingNotified=new Set();
let creatorData=null,creatorTab='overview',creatorRequested=false,creatorLoading=false,loggedIn=false,billingData=null,launchTab='strategy',launchRegion='Todas',launchPriority='Todas',planPeriod='monthly';
const presentationOnly=document.querySelector('meta[name="ayah-presentation"]')?.content==='true';
let portalRole='ceo',portalTab='overview',onboardingStep=0,focusEnds=0,focusTimer=null;
let review=emptyReview();try{const r=JSON.parse(localStorage.getItem(REVIEW_STORAGE_KEY));if(r?.version===1&&r.roleProfiles&&typeof r.roleProfiles==='object'&&Array.isArray(r.people)&&r.people.every(p=>p&&typeof p.name==='string'&&typeof p.channel==='string')&&Array.isArray(r.checklist))review=r;}catch{}
function saveReview(){try{localStorage.setItem(REVIEW_STORAGE_KEY,JSON.stringify(review));}catch{toast('Este navegador não salvou o teste. Você pode continuar nesta sessão.');}}
function savePresentationWorkspace(){try{localStorage.setItem('ayah-personal-preview',JSON.stringify(state));}catch{toast('Não foi possível guardar o teste neste navegador.');}}
function startPersonalPreview({empty=false}={}){if(!demo)realState=structuredClone(state);demo=true;if(empty)state=emptyState();else{try{const stored=JSON.parse(localStorage.getItem('ayah-personal-preview'));state=stored?.version===1&&stored.settings&&Array.isArray(stored.tasks)&&Array.isArray(stored.memories)?stored:emptyState();}catch{state=emptyState();}}view=state.onboarded?'today':'onboarding';onboardingStep=0;render();}
function setJourneyRoute(role,tab=''){window.history?.replaceState(null,'','#'+ROLE_PATHS[role]+(tab?'/'+tab:''));}
function openRequestedJourney(){const [path,tab]=window.location?.hash?.slice(1).split('/')||[];const role=Object.keys(ROLE_PATHS).find(r=>ROLE_PATHS[r]===path);if(!role){if(['today','agenda','memory','wellness','money','rhythm','week','settings','plans'].includes(path)){startPersonalPreview();if(state.onboarded){view=path;render();}return true;}return false;}if(role==='user'){startPersonalPreview();return true;}portalRole=role;portalTab=JOURNEYS[role].tabs.some(t=>t[0]===tab)?tab:'overview';view=review.roleProfiles[role]?'portal':'role-onboarding';render();return true;}
function portal(){return portalPage(portalRole,portalTab,review);}
const conversation=()=>CONVERSATION_STYLES[state.settings.conversationStyle||'warm'];
function setBusy(value){root.setAttribute('aria-busy',String(value));dialog.setAttribute('aria-busy',String(value));document.querySelectorAll('button[type=submit]').forEach(button=>button.disabled=value);}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4200);}
async function mutate(fn){if(busy)return false;busy=true;setBusy(true);const previous=structuredClone(state);try{fn(state);if(demo){savePresentationWorkspace();}else{const r=await fetch('/api/workspace',{method:'PUT',headers:{'Content-Type':'application/json',...(etag?{'If-Match':`"${etag}"`}:{})},body:JSON.stringify(state)});const j=await r.json();if(!r.ok)throw Error(j.error||'Não foi possível salvar.');etag=j.etag;realState=structuredClone(state);}render();return true;}catch(err){state=previous;toast(err.message);return false;}finally{busy=false;setBusy(false);}}
function quietWarning(time){const a=state.settings.quietStart,b=state.settings.quietEnd;return time&&(a>b?(time>=a||time<b):(time>=a&&time<b))?`<p class="notice">Este horário está no seu período de silêncio, de ${e(a)} a ${e(b)}. O compromisso fica salvo. Ajuste o silêncio se quiser receber o aviso neste horário.</p>`:'';}
function activity(s,title){s.activity.unshift({id:uid(),title,createdAt:new Date().toISOString()});s.activity=s.activity.slice(0,100);}
function demoState(){const s=emptyState(),day=currentDay();s.onboarded=true;s.name='Daniela';s.tasks=PARTNER_VISION.day.filter(d=>d.kind==='task').map((d,i)=>({id:uid(),title:d.title,date:day,time:d.time,due:dateTimeToISO(day,d.time,timezone()),timezone:timezone(),status:i===0?'done':'pending',priority:true,source:'Exemplo ilustrativo adaptado do material original da Dani',createdAt:new Date().toISOString()}));s.routines=PARTNER_VISION.day.filter(d=>d.kind==='water'||d.kind==='ritual').map(d=>({id:uid(),title:d.title,time:d.time,weekdays:[0,1,2,3,4,5,6],enabled:true,createdAt:new Date().toISOString()}));s.routineChecks=[{id:uid(),routineId:s.routines[0].id,date:day,createdAt:new Date().toISOString()}];s.expenses=[{id:uid(),title:'Almoço',category:'Alimentação',amount:42,currency:'BRL',direction:'expense',source:'Exemplo ilustrativo',createdAt:new Date().toISOString()},{id:uid(),title:'Uber para o aeroporto',category:'Transporte',amount:38.5,currency:'BRL',direction:'expense',source:'Exemplo ilustrativo',createdAt:new Date().toISOString()},{id:uid(),title:'Compras no mercado',category:'Mercado',amount:186.3,currency:'BRL',direction:'expense',source:'Exemplo ilustrativo',createdAt:new Date().toISOString()}];s.water=[{id:uid(),amount:300,createdAt:new Date().toISOString()}];s.memories=[{id:uid(),title:'O aniversário do meu filho é 22 de novembro.',source:'Exemplo ilustrativo informado por texto',createdAt:new Date().toISOString()},{id:uid(),title:'Os documentos da viagem estão na pasta verde.',source:'Exemplo ilustrativo informado por texto',createdAt:new Date().toISOString()}];return s;}
function welcome(){return presentation();}
function conversationField(){return `<label for="conversation-style">Como você gosta de conversar?</label><select id="conversation-style" name="conversationStyle">${Object.entries(CONVERSATION_STYLES).map(([key,value])=>`<option value="${key}" ${(state.settings.conversationStyle||'warm')===key?'selected':''}>${e(value.label)}</option>`).join('')}</select><p class="record-note">Você pode mudar o tom quando quiser.</p>`;}
function onboarding(){return `<main class="onboarding card">${brand()}<span class="pill mt-25px">Seu primeiro dia com a AYAH</span><h1>Um espaço<br>do seu jeito.</h1><ol class="onboarding-steps">${ONBOARDING_STEPS.map((t,i)=>`<li aria-current="${i===onboardingStep?'step':'false'}">0${i+1} · ${t}</li>`).join('')}</ol><form id="onboarding"><section class="onboarding-step" data-step="0" ${onboardingStep!==0?'hidden':''}><h2>Como podemos te chamar?</h2><label for="first-name">Seu nome</label><input id="first-name" name="name" required maxlength="60" autocomplete="given-name" placeholder="Seu primeiro nome"><label for="first-goal">O que mais ocupa sua cabeça?</label><select id="first-goal" name="goal"><option>Coisas que preciso lembrar</option><option>Uma rotina cheia</option><option>Gastos que se perdem</option><option>Tempo para cuidar de mim</option></select><button class="btn primary mt-22px" type="button" data-action="onboarding-next">Continuar ${icon('arrow')}</button></section><section class="onboarding-step" data-step="1" ${onboardingStep!==1?'hidden':''}><h2>Como você gosta de ser acompanhada ou acompanhado?</h2>${conversationField()}<label for="closing-time">A que horas você quer fechar o dia?</label><input id="closing-time" name="closingTime" type="time" value="20:30" required>${timezoneField()}<div class="ayah-actions"><button class="btn outline" type="button" data-action="onboarding-back">Voltar</button><button class="btn primary" type="button" data-action="onboarding-next">Continuar ${icon('arrow')}</button></div></section><section class="onboarding-step" data-step="2" ${onboardingStep!==2?'hidden':''}><h2>Vamos tirar uma coisa da cabeça?</h2><label for="first-memory">O que você quer guardar?</label><textarea id="first-memory" name="firstMemory" maxlength="500" required placeholder="Ex. Os documentos da viagem estão na pasta verde."></textarea><p class="record-note">Você poderá encontrar, editar e apagar essa memória depois.</p><p class="notice">Edição de apresentação. Os registros ficam apenas neste navegador. Use exemplos durante o teste.</p><div class="ayah-actions"><button class="btn outline" type="button" data-action="onboarding-back">Voltar</button><button class="btn primary" type="submit">Guardar e abrir meu dia ${icon('arrow')}</button></div></section></form><button class="btn mt-22px" data-view="presentation">${icon('back')} As quatro experiências</button><button class="link" data-action="demo">Ou explorar um dia de exemplo</button></main>`;}
function showOnboardingStep(){root.querySelectorAll('[data-step]').forEach(el=>el.hidden=Number(el.dataset.step)!==onboardingStep);root.querySelectorAll('.onboarding-steps li').forEach((el,i)=>el.setAttribute('aria-current',i===onboardingStep?'step':'false'));root.querySelector(`[data-step="${onboardingStep}"] input,[data-step="${onboardingStep}"] select,[data-step="${onboardingStep}"] textarea`)?.focus();}

function taskRow(t,{agenda=false}={}){const zone=t.timezone||DEFAULT_TIMEZONE,done=t.status==='done',overdue=!done&&t.due&&new Date(t.due)<new Date();return `<div class="task-row ${done?'task-done':''}">${agenda?`<div class="due-date"><b>${t.date?Number(t.date.slice(-2)):'—'}</b><small>${t.date?fmt(dateAtNoon(t.date,zone),{month:'short'},zone):'Sem data'}</small></div>`:''}<button class="check ${done?'checked':''}" data-action="toggle-task" data-id="${e(t.id)}" aria-label="${done?'Reabrir':'Concluir'} ${e(t.title)}">${done?icon('check'):''}</button><div class="task-copy"><strong>${e(t.title)}</strong><small>${t.priority?'Prioridade escolhida':'Compromisso'}${t.date?` · ${zone===timezone()&&t.date===currentDay()?'Hoje':fmt(dateAtNoon(t.date,zone),{day:'2-digit',month:'short'},zone)}`:' · Defina uma data'}${zone!==timezone()?' · '+e(timezoneLabels[zone]||zone):''}${done?' · Você confirmou a conclusão':''}</small></div><div class="task-actions">${t.time?`<span class="task-time ${overdue?'overdue':''}">${e(t.time)}</span>`:''}<button class="icon-btn" data-action="edit-task" data-id="${e(t.id)}" aria-label="Editar ${e(t.title)}">${icon('edit')}</button></div></div>`;}
function composer(){return `<section class="composer"><div class="row"><span class="color-var-green">${icon('spark')}</span><strong class="fs-12px">O que está na sua cabeça?</strong></div><form id="capture"><textarea name="capture" aria-label="Conte à AYAH o que você quer organizar" placeholder="Ex. Amanhã às 15h, aula de inglês. Gastei 42 reais no almoço. Guarde que os documentos estão na pasta verde." maxlength="3000"></textarea><div class="between"><p class="hint">A AYAH prepara os registros. Você confirma antes de salvar.</p><div class="composer-actions"><button class="voice" type="button" data-action="voice" aria-label="Usar voz">${icon('mic')}</button><button class="btn primary small" type="submit">Organizar ${icon('arrow')}</button></div></div><div class="quick-examples"><button type="button" data-action="example" data-text="Me lembra de estudar inglês amanhã às 15h">Compromisso</button><button type="button" data-action="example" data-text="Gastei 42 reais no almoço">Gasto</button><button type="button" data-action="example" data-text="Guarde que os documentos estão na pasta verde">Memória</button></div></form></section>`;}
function intro(title,description,action=''){return `<section class="page-intro between"><div><p class="caps">${e(nowDate())}</p><h1>${title}</h1><p>${description}</p></div>${action?`<div class="intro-action">${action}</div>`:''}</section>`;}
function today(){const stats=dailyStats(state,currentDay(),timezone()),priorities=state.tasks.filter(t=>t.priority&&t.status!=='done').slice(0,3),finished=state.tasks.filter(t=>t.priority&&t.status==='done'&&t.date===currentDay()),shown=[...priorities,...finished.slice(0,Math.max(0,3-priorities.length))],spend=state.expenses.filter(x=>x.direction==='expense'&&x.currency==='BRL'&&localDay(new Date(x.createdAt),timezone())===currentDay()).reduce((s,x)=>s+x.amount,0),waterPct=Math.min(100,stats.water/state.settings.waterGoal*100);return `${intro(`Seu dia, com espaço<br>para você${state.name?', '+e(state.name):''}.`,conversation().day,`<button class="btn outline small" data-action="new-task">${icon('plus')} Novo compromisso</button>`)}${carePanel(state,currentDay())}<div class="dashboard-grid"><div class="left-column"><section class="card hero-card"><div class="hero-text"><p class="caps color-var-violet mt-0">Ritual 3 + 1</p><h2>O importante cabe<br>em três prioridades.</h2><p>Escolha três prioridades. No fim do dia, conclua ou reorganize o que ficou.</p><button class="btn outline small" data-action="choose-priorities">Escolher minhas prioridades ${icon('arrow')}</button></div><div class="hero-orbit"><img class="app-life-photo" src="./media/aya-portrait.jpg" alt="Fotografia ilustrativa da campanha AYAH" width="140" height="140"></div></section><section class="card priority-card mt-23px"><div class="section-head between"><div><h3>O que importa hoje</h3><p>Um passo de cada vez, no seu ritmo.</p></div><span class="pill">${finished.length} concluída${finished.length===1?'':'s'}</span></div>${shown.length?shown.map(t=>taskRow(t)).join(''):`<div class="priority-empty">${icon('sun')}<p>Escolha suas primeiras prioridades.<br>Seu dia começa com o que importa para você.</p></div>`}<div class="mt-20px"><div class="between fs-10px color-var-muted mb-10px"><span>Compromissos de hoje</span><span>${stats.done} de ${stats.tasks}</span></div><div class="progress"><span data-progress="${stats.progress}"></span></div></div></section>${composer()}</div><aside class="right-column stack"><section class="card money-mini"><div><span class="caps color-var-accent-sand">Seus registros de hoje</span><div class="money">${money(spend)}</div><small>Despesas informadas em reais</small><p class="mt-12px"><button class="link" data-view="money">Ver meu dinheiro ${icon('arrow')}</button></p></div><span class="mini-icon">${icon('wallet')}</span></section><section class="card habits-card"><div class="between"><h3>Um cuidado com você</h3><span class="pill lilac">Bem-estar</span></div><div class="water-display"><span class="water-icon">${icon('drop')}</span><div><div class="water-amount">${(stats.water/1000).toLocaleString('pt-BR')} <span class="muted fs-12px">/ ${(state.settings.waterGoal/1000).toLocaleString('pt-BR')} L</span></div><small>Água que você registrou hoje</small></div></div><div class="progress water-progress"><span data-progress="${waterPct}"></span></div><div class="between mt-19px"><small>Uma pausa também é prioridade.</small><button class="btn soft small" data-action="water">+ 250 ml</button></div></section><section class="card closing-mini"><div class="row color-var-green mb-12px">${icon('moon')}<span class="caps">Fechamento do dia · ${e(state.settings.closingTime)}</span></div><h3>Um dia resolvido.<br>Uma cabeça mais leve.</h3><p>Veja o que concluiu e decida, com calma, o que fica para amanhã.</p><button class="btn outline small" data-action="closing">Fechar meu dia ${icon('arrow')}</button></section></aside></div><p class="footer-note">Sua memória, suas escolhas. Informações registradas por você, sempre editáveis.</p>`;}
function agenda(){let tasks=state.tasks.filter(x=>filter==='all'||(filter==='done'?x.status==='done':x.status!=='done')).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));return `${intro('Tudo no seu tempo.','Compromissos, prioridades e espaço para reorganizar.',`<button class="btn primary small" data-action="new-task">${icon('plus')} Novo compromisso</button>`)}<div class="filter-row">${[['all','Todos'],['pending','Em aberto'],['done','Concluídos']].map(([k,v])=>`<button class="${filter===k?'active':''}" data-filter="${k}" aria-pressed="${filter===k}">${v}</button>`).join('')}</div><section class="card wide-list">${tasks.length?tasks.map(t=>taskRow(t,{agenda:true})).join(''):empty('calendar','Sua agenda está pronta para começar.','Registre um compromisso com data e horário.','new-task','Adicionar compromisso')}</section>${composer()}`;}
function empty(i,title,desc,action,label){return `<div class="empty-card">${icon(i)}<h3 class="mt-15px">${title}</h3><p>${desc}</p>${action?`<button class="btn soft small" data-action="${action}">${label}</button>`:''}</div>`;}
function memory(){const records=state.memories.filter(x=>normalize(x.title+' '+x.source).includes(normalize(search)));return `${intro('O que importa fica.','Guarde, encontre e corrija. A memória continua nas suas mãos.',`<button class="btn primary small" data-action="new-memory">${icon('plus')} Guardar uma informação</button>`)}<div class="filter-row"><input class="search" id="memory-search" type="search" placeholder="Buscar na sua memória" aria-label="Buscar na memória" value="${e(search)}"><span class="pill">${state.memories.length} registro${state.memories.length===1?'':'s'}</span></div><div class="records-grid">${records.length?records.map(x=>`<article class="card memory-card"><div class="between"><span class="pill lilac">${icon('memory')} Memória confirmada</span><div class="row"><button class="icon-btn" data-action="edit-memory" data-id="${e(x.id)}" aria-label="Editar memória">${icon('edit')}</button><button class="icon-btn danger" data-action="delete-memory" data-id="${e(x.id)}" aria-label="Excluir memória">${icon('trash')}</button></div></div><p>${e(x.title)}</p><div class="source">Origem · ${e(x.source)}<br>Registrado em ${fmt(x.createdAt,{day:'numeric',month:'long',year:'numeric'})}</div></article>`).join(''):`<section class="card grid-1-1">${empty('memory','Um lugar para o que você quer lembrar.',search?'Nenhuma informação corresponde à sua busca.':'Datas importantes, lugares, preferências e pequenas informações.','new-memory','Guardar uma informação')}</section>`}</div>${composer()}`;}
function wellness(){const d=dailyStats(state,currentDay(),timezone()),pct=Math.min(100,d.water/state.settings.waterGoal*100),todayWater=state.water.filter(x=>localDay(new Date(x.createdAt),timezone())===currentDay());return `${intro('Cuidar também cabe no dia.','Pequenos registros para acompanhar os cuidados que você escolheu.')}<div class="two-col"><section class="card"><div class="between"><h2>Minha água de hoje</h2><span class="pill lilac">Meta definida por você</span></div><div class="water-display m-35px-0"><span class="water-icon h-95px w-80px">${icon('drop')}</span><div><div class="water-amount fs-38px">${d.water} <span class="muted fs-15px">/ ${state.settings.waterGoal} ml</span></div><small>Acompanhamento por autorregistro, sem sensor.</small></div></div><div class="progress water-progress"><span data-progress="${pct}"></span></div><div class="row mt-25px"><button class="btn soft" data-action="water">${icon('plus')} 250 ml</button><button class="btn outline" data-action="water-custom">Outra quantidade</button></div><p class="record-note">A meta é uma preferência pessoal. Ajuste conforme sua orientação profissional.</p></section><section class="card"><span class="caps muted">Ritual de cuidado</span><h2 class="m-18px-0-15px">Seu cuidado, no seu ritmo.</h2><p class="muted fs-13px">Traga uma pequena ação de bem-estar para suas prioridades. Ela merece espaço junto com seus compromissos.</p><div class="stack mt-22px">${[['Reservar um tempo para o inglês','Me lembra de estudar inglês amanhã às 15h'],['Fazer uma pausa','Me lembra de fazer uma pausa hoje às 16h'],['Ir à igreja','Me lembra de ir à igreja domingo às 20h']].map(([label,text])=>`<button class="btn outline" data-action="capture-text" data-text="${e(text)}">${e(label)} ${icon('arrow')}</button>`).join('')}</div></section></div><section class="card mt-22px"><h3>Seus registros de água</h3>${todayWater.length?todayWater.slice().reverse().map(x=>`<div class="task-row"><span class="pill">${icon('drop')} ${x.amount} ml</span><div class="task-copy"><small>${fmt(x.createdAt,{hour:'2-digit',minute:'2-digit'})} · Você informou</small></div><button class="icon-btn" data-action="delete-water" data-id="${e(x.id)}" aria-label="Excluir registro de água">${icon('trash')}</button></div>`).join(''):'<p class="muted mt-20px">Nenhum registro hoje.</p>'}</section>`;}
function finance(){const currencies=[...new Set(state.expenses.map(x=>x.currency))],brl=state.expenses.filter(x=>x.currency==='BRL'),spend=brl.filter(x=>x.direction==='expense').reduce((s,x)=>s+x.amount,0),income=brl.filter(x=>x.direction==='income').reduce((s,x)=>s+x.amount,0),cats={};brl.filter(x=>x.direction==='expense').forEach(x=>cats[x.category]=(cats[x.category]||0)+x.amount);return `${intro('Seu dinheiro, com clareza.','Uma visão simples dos valores que você registrou.',`<button class="btn primary small" data-action="new-expense">${icon('plus')} Registrar valor</button>`)}${budgetPanel(state,new Date(),timezone())}<div class="cards3"><section class="card metric"><span class="caps muted">Entradas registradas · BRL</span><div class="value income">${money(income)}</div><small>Todos os registros informados</small></section><section class="card metric bg-var-peach"><span class="caps muted">Saídas registradas · BRL</span><div class="value">${money(spend)}</div><small>${brl.filter(x=>x.direction==='expense').length} despesas registradas</small></section><section class="card metric bg-var-green-soft"><span class="caps muted">Diferença registrada · BRL</span><div class="value">${money(income-spend)}</div><small>Entradas menos saídas. Não é saldo bancário.</small></section></div>${currencies.filter(x=>x!=='BRL').map(c=>`<p class="record-note">${c} · ${money(state.expenses.filter(x=>x.currency===c&&x.direction==='expense').reduce((s,x)=>s+x.amount,0),c)} em despesas. Moedas não são somadas nem convertidas.</p>`).join('')}<div class="two-col mt-22px"><section class="card"><div class="between"><h3>Seus últimos registros</h3><button class="link" data-action="export-expenses">Exportar CSV ${icon('download')}</button></div>${state.expenses.length?`<div class="table-scroll"><table class="expense-list"><thead><tr><th>Descrição</th><th>Categoria</th><th>Valor</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody>${state.expenses.slice().reverse().map(x=>`<tr><td>${e(x.title)}<br><small>${fmt(x.createdAt)}</small></td><td>${e(x.category)}</td><td class="amount ${x.direction==='income'?'income':''}">${x.direction==='income'?'+':'−'}${money(x.amount,x.currency)}</td><td><button class="icon-btn" data-action="edit-expense" data-id="${e(x.id)}" aria-label="Editar registro">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('wallet','Comece com um registro.','Informe um gasto ou uma entrada, sem conectar seu banco.','new-expense','Registrar valor')}</section><section class="card"><h3>Para onde foi o dinheiro</h3><p class="muted fs-11px mt-7px">Despesas registradas em reais</p>${Object.keys(cats).length?Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([c,v])=>`<div class="category-bar"><div class="between"><span>${e(c)}</span><span>${money(v)}</span></div><div class="progress"><span data-progress="${spend?v/spend*100:0}"></span></div></div>`).join(''):'<p class="muted fs-12px mt-30px">As categorias aparecem depois do primeiro registro.</p>'}<div class="notice">Visão dos registros que você informou. Bancos, cartões, pagamentos e conciliação ainda não estão conectados.</div></section></div>${composer()}`;}
function week(){const start=new Date();start.setUTCDate(start.getUTCDate()-6);const done=state.tasks.filter(x=>x.status==='done'&&x.completedAt&&new Date(x.completedAt)>=start),closings=state.closings.filter(x=>new Date(x.createdAt)>=start),recent=state.activity.slice(0,10);return `${intro('Um pouco mais de clareza.','Veja o que você confirmou e o que ainda merece espaço.')}${weeklyCharts(state,new Date(),timezone())}<div class="cards3"><section class="card metric"><span class="caps muted">Nos últimos sete dias</span><div class="value">${done.length}</div><small>Compromissos que você confirmou como concluídos</small></section><section class="card metric"><span class="caps muted">Seu ritual de fechamento</span><div class="value">${closings.length}</div><small>Fechamentos registrados nos últimos sete dias</small></section><section class="card metric"><span class="caps muted">Ainda em aberto</span><div class="value">${state.tasks.filter(x=>x.status!=='done').length}</div><small>Compromissos para organizar, concluir ou reagendar</small></section></div><div class="two-col mt-22px"><section class="card"><div class="between"><h3>Seus fechamentos</h3><button class="link" data-action="closing">Fechar hoje ${icon('arrow')}</button></div><div class="week-rows">${state.closings.length?state.closings.slice().reverse().map(x=>`<article class="week-row"><div><b>${fmt(x.createdAt,{day:'numeric',month:'long'})}</b><p class="muted">${e(x.note||'Fechamento registrado.')}</p></div><span class="pill">${x.done} concluídos</span></article>`).join(''):'<p class="muted fs-12px">Seu primeiro fechamento aparece aqui.</p>'}</div></section><section class="card"><h3>O que aconteceu</h3><div class="week-rows">${recent.length?recent.map(x=>`<div class="row"><span class="color-var-green">${icon('check')}</span><div><p class="fs-12px">${e(x.title)}</p><small>${fmt(x.createdAt,{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join(''):'<p class="muted fs-12px">Seus registros e ações aparecerão aqui.</p>'}</div></section></div>`;}
function calcCosts(container){if(!container)return;const get=id=>Math.max(0,Number(container.querySelector('#'+id)?.value)||0),result=container.querySelector('#cost-result');if(!result)return;const fee=get('cost-fee')/100,aff=get('cost-affiliate')/100,cost=get('cost-fixed')+get('cost-messages')*get('cost-message');result.innerHTML=PLANS.map(plan=>{const price=plan.amountMinor/100/plan.months,net=price*(1-fee-aff),contribution=net-cost;return `<tr><td>${e(plan.name)}${plan.status==='suspended'?' · suspenso':''}</td><td>${money(price)}</td><td>${money(net)}</td><td>${money(cost)}</td><td class="${contribution<0?'danger':'income'}">${money(contribution)}</td></tr>`;}).join('');}
const subscriptionLabels={active:'Ativa',trialing:'Em experimentação',past_due:'Pagamento precisa de atenção',pending:'Checkout em aberto',processing:'Pagamento em confirmação',canceled:'Cancelada',unpaid:'Pagamento não confirmado',incomplete:'Pagamento em confirmação',incomplete_expired:'Checkout expirado'};
function plans(){const options=PLANS.filter(p=>p.id===(planPeriod==='annual'?'annual':'monthly')||p.id===(planPeriod==='annual'?'rhythm_annual':'rhythm'));return `${intro('Fica tudo solto no seu dia?','Comece pelo essencial. Escolha mais apoio quando fizer sentido.')}<div class="creator-tabs" aria-label="Período do plano"><button data-action="plan-period" data-period="monthly" aria-current="${planPeriod==='monthly'?'page':'false'}">Por mês</button><button data-action="plan-period" data-period="annual" aria-current="${planPeriod==='annual'?'page':'false'}">Por ano · 12 meses pelo preço de 10</button></div>${!status.payments?'<p class="notice">Você pode experimentar a AYAH no piloto. A assinatura está em preparação e nenhuma cobrança é feita nesta tela.</p>':''}${billingData?.subscription?`<section class="card mb-22px"><h2>Minha assinatura</h2><p>${e(subscriptionLabels[billingData.subscription.status]||'Em revisão')} · ${e(PLANS.find(p=>p.id===billingData.subscription.plan)?.name||'Seu plano')}</p><button class="btn outline" data-action="billing-portal">Ver pagamentos e cancelamento ${icon('arrow')}</button></section>`:''}<div class="plans">${options.map(plan=>`<section class="card plan ${plan.tier==='rhythm'?'recommended':''}"><span class="caps muted">${plan.tier==='rhythm'?'PARA A SEMANA TAMBÉM':'PARA O QUE IMPORTA HOJE'}</span><h2>${e(plan.name)}</h2><div class="price">${money(plan.amountMinor/100)}</div><small>${e(plan.period)}${plan.months===12?' · '+money(plan.amountMinor/100/12)+'/mês equivalente':''}</small><p>${e(plan.description)}</p><ul>${plan.items.map(item=>`<li>${icon('check')} ${e(item)}</li>`).join('')}</ul><button class="btn ${plan.tier==='rhythm'?'primary':'outline'}" data-action="${status.payments?'checkout':'plan'}" data-plan="${plan.id}">${status.payments?'Escolher este plano':state.planInterest===plan.id?'Interesse registrado':'Quero experimentar'}</button><p class="plan-note">Renovação e cancelamento visíveis. O canal e os limites de uso são informados antes da compra.</p></section>`).join('')}</div><section class="card mt-22px"><h2>Seu jeito de conversar já faz parte.</h2><p>Mais direto, mais acolhedor ou mais leve. Você escolhe nos ajustes. O plano Seu ritmo acrescenta listas e repetições para a semana, sem cobrar para mudar o tom.</p><button class="btn outline" data-view="rhythm">Ver um ritual ${icon('arrow')}</button></section>`;}
function affiliate(){if(demo)return creatorPortal(null,{tab:creatorTab,logged:false,loading:false});if(loggedIn&&!creatorRequested){creatorRequested=true;Promise.resolve().then(loadCreator);}return creatorPortal(creatorData,{tab:creatorTab,logged:loggedIn,loading:creatorLoading});}
function launch(){return launchPage({tab:launchTab,region:launchRegion,priority:launchPriority});}
function rhythm(){return rhythmPage(state,{demo});}
async function portalApi(path,body){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const value=await response.json();if(!response.ok)throw Error(value.error||'Não foi possível concluir.');return value;}
async function loadBilling(){try{const response=await fetch('/api/billing/status');if(!response.ok)throw Error();billingData=await response.json();}catch{billingData=null;}}
async function loadCreator(){creatorLoading=true;try{const response=await fetch('/api/affiliate');const value=await response.json();if(!response.ok)throw Error(value.error);creatorData=value;}catch(error){creatorData={error:error.message};}finally{creatorLoading=false;if(view==='affiliate')render();}}
async function copyVisible(text){if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);toast('Copiado.');return;}catch{}}showDialog('<h2>Copie este conteúdo.</h2><textarea readonly aria-label="Conteúdo para copiar">'+e(text)+'</textarea><div class="dialog-footer"><button class="btn primary" data-dialog="close">Fechar</button></div>');}
function routineDialog(preset){showDialog(`<h2>Um pequeno passo para repetir.</h2><p>Você escolhe os dias. O ritual aparece no seu checklist, sem depender de uma sequência perfeita.</p><form id="routine-form"><label>Qual é o primeiro passo?</label><input name="title" required maxlength="160" value="${e(preset?.items?.[0]||'')}" placeholder="Conferir o que preciso levar"><label>Qual horário faz sentido?</label><input name="time" type="time" value="08:30" required><fieldset class="rhythm-weekdays"><legend>Em quais dias?</legend>${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((label,n)=>`<label class="toggle"><input name="weekday" type="checkbox" value="${n}" ${n>0&&n<6?'checked':''}>${label}</label>`).join('')}</fieldset>${preset?`<p class="notice">Outras ideias para adaptar<br>${preset.items.map(e).join('<br>')}</p>`:''}<p class="record-note">Um checklist por dia. Avisos desta versão precisam da página aberta.</p><div class="dialog-footer"><button class="btn outline" type="button" data-dialog="close">Voltar</button><button class="btn primary" type="submit">Criar meu ritual</button></div></form>`);}
function settings(){return `${intro('Sua AYAH, do seu jeito.','Você escolhe o ritmo, os horários e o que fica guardado.')}<div class="settings-grid stack"><form id="settings" class="card"><h3>Seu ritmo</h3><label for="settings-name">Seu nome</label><input id="settings-name" name="name" value="${e(state.name)}" maxlength="60" required><div class="two-col"><div><label for="goal">Meta pessoal de água em ml</label><input id="goal" name="waterGoal" type="number" min="250" max="6000" step="50" value="${state.settings.waterGoal}" required></div><div><label for="close-time">Horário do fechamento</label><input id="close-time" type="time" name="closingTime" value="${e(state.settings.closingTime)}" required></div></div><div class="two-col"><div><label for="quiet-start">Silêncio a partir de</label><input id="quiet-start" type="time" name="quietStart" value="${e(state.settings.quietStart)}" required></div><div><label for="quiet-end">Voltar a avisar às</label><input id="quiet-end" type="time" name="quietEnd" value="${e(state.settings.quietEnd)}" required></div></div>${timezoneField()}${conversationField()}<label class="toggle"><input name="followUp" type="checkbox" ${state.settings.followUp?'checked':''}>Mostrar pendências no fechamento</label><button class="btn primary small mt-19px" type="submit">Salvar preferências</button></form><section class="card"><h3>Canais e conexões</h3><div class="setting-row between"><div><strong class="fs-12px">Seu espaço web</strong><p>Registros privados salvos na sua conta.</p></div><span class="pill"><span class="dot"></span>${demo?'Demonstração':status.storage?'Ativo':'Preparando'}</span></div><div class="setting-row between"><div><strong class="fs-12px">WhatsApp</strong><p>Número e conta oficial ainda não conectados.</p></div><span class="pill badge-off">Pendente</span></div><div class="setting-row between"><div><strong class="fs-12px">Pagamentos</strong><p>Checkout, assinatura e comissões.</p></div><span class="pill badge-off">Pendente</span></div><div class="setting-row between"><div><strong class="fs-12px">Notificações do navegador</strong><p>Lembretes enquanto este espaço está aberto.</p></div><button class="btn outline small" data-action="notifications">Permitir</button></div><div class="notice">Os lembretes desta versão aparecem com a página aberta. Entrega com a página fechada e envio pelo WhatsApp dependem da ativação do canal.</div></section><section class="card"><h3>Seus dados continuam seus</h3><p class="muted fs-12px mt-12px">Exporte seus registros quando quiser. Você também pode editar ou excluir cada informação.</p><button class="btn outline small mt-20px" data-action="export">${icon('download')} Exportar meus dados</button><p class="record-note">AYAH · Sua vida, em equilíbrio. useayah.com</p></section></div>`;}
function render(){if(view==='role-onboarding'){root.innerHTML=journeyOnboarding(portalRole,review);return;}if(view==='portal'){root.innerHTML=portal();return;}if(view==='presentation'){root.innerHTML=presentation();return;}if(view==='onboarding'){root.innerHTML=onboarding();return;}if(!state.onboarded&&!['presentation','partner','research','ecosystem','design','plans','affiliate','launch'].includes(view)){root.innerHTML=welcome();return;}const label=view==='design'?'Design system':nav.find(x=>x[0]===view)?.[2]||'Planos';root.innerHTML=`<div class="shell"><a class="skip-link" href="#main-content">Ir ao conteúdo</a><div class="menu-backdrop" data-action="close-menu" hidden></div><aside class="sidebar" id="primary-sidebar" tabindex="-1"><button class="icon-btn mobile-menu-close" data-action="close-menu" aria-label="Fechar navegação">${icon('close')}</button>${brand()}<p class="brand-note">SEU DIA EM BOAS MÃOS</p><p class="nav-label caps muted">Seu espaço</p><nav class="nav" aria-label="Navegação principal">${nav.filter(([id])=>!['partner','research','launch','design','ecosystem','affiliate'].includes(id)).map(([id,i,label])=>`<button data-view="${id}" aria-current="${view===id?'page':'false'}" class="${view===id?'active':''}">${icon(i)}${label}${id==='agenda'&&state.tasks.filter(t=>t.status!=='done').length?`<span class="count">${state.tasks.filter(t=>t.status!=='done').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">Três prioridades.<br>Um fechamento.<br><strong>Mais espaço para viver.</strong></div><div class="profile"><span class="avatar">${e(state.name.slice(0,1).toUpperCase()||'A')}</span><div><strong class="fs-11px">${e(state.name||'Seu espaço')}</strong><p class="fs-10px color-var-muted mt-3px">${demo?'Conta demonstrativa':'Primeira experiência'}</p></div></div></div></aside><main class="main"><header class="topbar"><div class="mobile-brand"><button class="icon-btn menu-toggle" data-action="menu" aria-controls="primary-sidebar" aria-expanded="false" aria-label="Abrir navegação">${icon('menu')}</button>${brand()}</div><div class="breadcrumb">Seu espaço <span>/ &nbsp; ${label}</span></div><div class="top-actions"><span class="capsule"><span class="dot mr-7px"></span>${demo?'Modo demonstração':'Seu espaço privado'}</span><button class="icon-btn" data-action="reminders" aria-label="Ver lembretes">${icon('bell')}</button><button class="btn outline small" data-view="plans">Conhecer planos ${icon('arrow')}</button></div></header>${demo?'<div class="banner"><span>Edição de apresentação · seus testes ficam apenas neste navegador.</span><button class="link" data-view="presentation">Trocar experiência</button></div>':''}<div class="content" id="main-content" tabindex="-1">${({today,agenda,memory,wellness,money:finance,week,rhythm,affiliate,launch,settings,plans,presentation,partner:partnerVision,research,design:designSystem,ecosystem}[view]||today)()}</div></main><nav class="bottom-nav" aria-label="Navegação do app"><button data-view="today" aria-current="${view==='today'?'page':'false'}">${icon('home')}<span>Meu dia</span></button><button data-view="agenda" aria-current="${view==='agenda'?'page':'false'}">${icon('calendar')}<span>Agenda</span></button><button class="bottom-compose" data-action="compose" aria-label="Organizar uma mensagem">${icon('plus')}<span>Organizar</span></button><button data-view="memory" aria-current="${view==='memory'?'page':'false'}">${icon('memory')}<span>Memória</span></button><button data-action="menu" aria-label="Mais telas">${icon('menu')}<span>Mais</span></button></nav></div>`;root.querySelectorAll('[data-progress]').forEach(el=>el.style.setProperty('--progress-value',el.dataset.progress+'%'));menuOpen=false;syncMenu();if(view==='research')calcCosts(root.querySelector('.research'));}
function syncMenu(){const sidebar=root.querySelector('.sidebar');if(!sidebar)return;const mobile=window.matchMedia('(max-width: 767px)').matches,open=mobile&&menuOpen;sidebar.classList.toggle('open',open);sidebar.inert=mobile&&!open;sidebar.setAttribute('aria-label','Seu espaço');if(mobile){sidebar.setAttribute('aria-hidden',String(!open));if(open){sidebar.setAttribute('role','dialog');sidebar.setAttribute('aria-modal','true');}else{sidebar.removeAttribute('role');sidebar.removeAttribute('aria-modal');}}else{sidebar.removeAttribute('aria-hidden');sidebar.removeAttribute('role');sidebar.removeAttribute('aria-modal');}const toggle=root.querySelector('.menu-toggle');toggle?.setAttribute('aria-expanded',String(open));const backdrop=root.querySelector('.menu-backdrop');if(backdrop)backdrop.hidden=!open;const main=root.querySelector('.main');if(main)main.inert=open;const bottom=root.querySelector('.bottom-nav');if(bottom)bottom.inert=open;}
function setMenu(open){menuOpen=open;if(open)menuReturnFocus=document.activeElement;syncMenu();if(open)root.querySelector('.mobile-menu-close')?.focus();else menuReturnFocus?.focus();}
function labelFields(container){container.querySelectorAll('label:not([for])').forEach((label,index)=>{if(label.querySelector('input,textarea,select'))return;const field=label.nextElementSibling;if(!field?.matches('input,textarea,select'))return;field.id=field.id||`dialog-field-${index}`;label.htmlFor=field.id;});}
function showDialog(html,action){dialogReturnFocus=document.activeElement;dialog.innerHTML=html;dialogAction=action;labelFields(dialog);const title=dialog.querySelector('h2');if(title){title.id='dialog-title';dialog.setAttribute('aria-labelledby','dialog-title');}const description=dialog.querySelector('h2 + p');if(description){description.id='dialog-description';dialog.setAttribute('aria-describedby','dialog-description');}else dialog.removeAttribute('aria-describedby');dialog.showModal();}
function closeDialog(){dialog.close();dialogAction=null;pending=[];}
function validForm(form){form.querySelectorAll('input[required],textarea[required]').forEach(field=>{field.setCustomValidity((field.type==='text'||field.tagName==='TEXTAREA')&&!field.value.trim()?'Preencha este campo.':'');});return form.reportValidity();}
dialog.addEventListener('close',()=>{dialogAction=null;pending=[];if(dialogReturnFocus?.isConnected)dialogReturnFocus.focus();else root.querySelector('button[aria-current=page]')?.focus();});
dialog.addEventListener('input',event=>event.target.setCustomValidity?.(''));
window.addEventListener('hashchange',()=>{if(window.location.hash==='#presentation'){view='presentation';render();return;}openRequestedJourney();});
window.addEventListener('resize',()=>{if(!window.matchMedia('(max-width: 767px)').matches)menuOpen=false;syncMenu();});
document.addEventListener('keydown',event=>{if(!menuOpen)return;if(event.key==='Escape'){event.preventDefault();setMenu(false);return;}if(event.key==='Tab'){const items=[...root.querySelectorAll('.sidebar button,.sidebar a[href]')].filter(el=>!el.disabled);if(!items.length)return;const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
function previewCapture(text){pending=parseCapture(text,new Date(),timezone());if(!pending.length)return toast('Conte o que você quer organizar.');const queries=pending.filter(x=>x.kind==='query');pending=pending.filter(x=>x.kind!=='query');const queryResults=queries.map(q=>{const matches=queryMemory(q.source,state);return `<section class="preview-item"><h3>${e(q.source)}</h3><p>A busca usa apenas seus registros confirmados.</p>${matches.length?matches.map(x=>`<div class="search-results"><strong>${e(x.title)}</strong><div class="source">Origem · ${e(x.source)}<br>Registrado em ${fmt(x.createdAt)}</div></div>`).join(''):'<div class="notice">Não encontrei uma informação confirmada correspondente.</div>'}</section>`;}).join('');if(!pending.length){showDialog(`<h2>Consulta dos seus registros</h2>${queryResults}<div class="dialog-footer"><button class="btn outline small" data-dialog="close">Fechar</button></div>`);return;}
  const titles={task:'Compromisso',memory:'Memória',expense:'Registro financeiro',water:'Água'};
  showDialog(`<h2>Vamos deixar em ordem.</h2><p>Confira o que foi preparado. Ajuste antes de confirmar.</p>${queryResults}<form id="preview-capture">${pending.map((x,i)=>`<section class="preview-item" data-preview="${i}"><div class="between"><span class="pill ${x.kind==='memory'?'lilac':''}">${titles[x.kind]}</span><small>Origem preservada</small></div>${x.warnings?.length?`<div class="notice" role="status">${x.warnings.map(w=>e(w)).join('<br>')}</div>`:''}<label>Descrição</label><input name="title-${i}" value="${e(x.title)}" required maxlength="500">${x.kind==='task'?`${quietWarning(x.time)}<div class="two-col"><div><label>Data</label><input name="date-${i}" type="date" value="${e(x.date)}" required></div><div><label>Horário</label><input name="time-${i}" type="time" value="${e(x.time)}" required></div></div><label class="toggle"><input type="checkbox" name="priority-${i}" ${i<Math.max(0,3-state.tasks.filter(t=>t.priority&&t.status!=='done').length)?'checked':''}>Escolher como prioridade</label>${!x.date||!x.time?'<p class="error">Defina a data e o horário. A AYAH não escolhe por você.</p>':''}`:''}${x.kind==='expense'?`<div class="two-col"><div><label>Valor</label><input name="amount-${i}" type="number" step="0.01" min="0.01" max="99999999" value="${x.amount??''}" required></div><div><label>Moeda</label><select name="currency-${i}">${['BRL','EUR','USD'].map(c=>`<option ${x.currency===c?'selected':''}>${c}</option>`).join('')}</select></div></div><label>Categoria</label><select name="category-${i}">${['Mercado','Alimentação','Transporte','Saúde','Casa','Viagem','Outros'].map(c=>`<option ${x.category===c?'selected':''}>${c}</option>`).join('')}</select>`:''}${x.kind==='water'?`<label>Quantidade em ml</label><input name="amount-${i}" type="number" min="0.01" max="6000" step="0.01" value="${x.amount??''}" required>`:''}<div class="source">${e(x.source)}${x.kind==='task'?`<br>Fuso · ${e(timezoneLabels[x.timezone||timezone()])}`:''}</div></section>`).join('')}<p class="notice">Interpretamos formatos comuns nesta versão. Registros ambíguos precisam da sua confirmação. Você pode editar tudo depois.</p><div class="dialog-footer"><button class="btn outline" type="button" data-dialog="close">Cancelar</button><button class="btn primary" type="submit">Confirmar ${pending.length} registro${pending.length===1?'':'s'} ${icon('check')}</button></div></form>`,'capture');
}
function taskDialog(id){const x=state.tasks.find(t=>t.id===id);showDialog(`<h2>${x?'Ajuste seu compromisso.':'Um espaço para o que importa.'}</h2><p>Você escolhe quando e como acompanhar.</p><form id="task-form" data-id="${e(id||'')}"><label>Compromisso</label><input name="title" value="${e(x?.title||'')}" maxlength="500" required><div class="two-col"><div><label>Data</label><input name="date" type="date" value="${x?.date||currentDay()}" required></div><div><label>Horário</label><input name="time" type="time" value="${e(x?.time||'')}" required></div></div><label class="toggle"><input name="priority" type="checkbox" ${x?.priority?'checked':''}>Uma das minhas três prioridades</label>${timezoneField(x?x.timezone||DEFAULT_TIMEZONE:timezone(),'task-timezone')}${x?`<div class="source">Origem · ${e(x.source)}<br>Registrado em ${fmt(x.createdAt)}</div>`:''}<div class="dialog-footer">${x?`<button class="btn danger" type="button" data-dialog="delete-task" data-id="${e(id)}">Excluir</button>`:''}<button class="btn outline" type="button" data-dialog="close">Cancelar</button><button class="btn primary" type="submit">Salvar compromisso</button></div></form>`);}
function memoryDialog(id){const x=state.memories.find(t=>t.id===id);showDialog(`<h2>Guarde o que importa.</h2><p>Uma informação clara que você poderá consultar depois. Não guarde senhas, tokens ou credenciais.</p><form id="memory-form" data-id="${e(id||'')}"><label>Informação</label><textarea name="title" required maxlength="1500">${e(x?.title||'')}</textarea>${x?`<div class="source">Origem · ${e(x.source)}</div>`:''}<div class="dialog-footer"><button class="btn outline" type="button" data-dialog="close">Cancelar</button><button class="btn primary" type="submit">Guardar informação</button></div></form>`);}
function expenseDialog(id){const x=state.expenses.find(t=>t.id===id);showDialog(`<h2>Seu registro financeiro.</h2><p>Valores informados por você, sem movimentar dinheiro.</p><form id="expense-form" data-id="${e(id||'')}"><label>Descrição</label><input name="title" value="${e(x?.title||'')}" maxlength="500" required><div class="two-col"><div><label>Valor</label><input name="amount" type="number" min="0.01" max="99999999" step="0.01" required value="${x?.amount||''}"></div><div><label>Moeda</label><select name="currency">${['BRL','EUR','USD'].map(c=>`<option ${x?.currency===c?'selected':''}>${c}</option>`).join('')}</select></div></div><div class="two-col"><div><label>Tipo</label><select name="direction"><option value="expense" ${x?.direction==='expense'?'selected':''}>Despesa</option><option value="income" ${x?.direction==='income'?'selected':''}>Entrada</option></select></div><div><label>Categoria</label><select name="category">${['Mercado','Alimentação','Transporte','Saúde','Casa','Viagem','Outros'].map(c=>`<option ${x?.category===c?'selected':''}>${c}</option>`).join('')}</select></div></div><div class="dialog-footer">${x?`<button class="btn danger" type="button" data-dialog="delete-expense" data-id="${e(id)}">Excluir</button>`:''}<button class="btn outline" type="button" data-dialog="close">Cancelar</button><button class="btn primary" type="submit">Salvar registro</button></div></form>`);}
function closingDialog(){const d=dailyStats(state,currentDay(),timezone()),open=state.tasks.filter(t=>t.status!=='done'&&t.date<=currentDay());showDialog(`<h2>O dia pode terminar aqui.</h2><p>Você confirmou ${d.done} de ${d.tasks} compromissos de hoje. O que ainda está aberto pode ganhar um novo horário.</p>${open.length?`<div class="notice">${open.length} compromisso${open.length===1?'':'s'} em aberto. Você escolhe o que reagendar, sem marcar como concluído automaticamente.</div>${open.map(t=>`<div class="task-row"><div class="task-copy"><strong>${e(t.title)}</strong><small>${e(t.time||'Sem horário')}</small></div><button class="btn soft small" data-dialog="reschedule" data-id="${e(t.id)}">Reagendar</button></div>`).join('')}`:'<div class="notice">Nenhum compromisso de hoje em aberto. Você pode registrar seu fechamento.</div>'}<form id="closing-form"><label>O que você quer guardar deste dia?</label><textarea name="note" placeholder="Uma pequena conquista, algo para reorganizar ou um cuidado para amanhã." maxlength="1000"></textarea><div class="dialog-footer"><button class="btn outline" type="button" data-dialog="close">Voltar</button><button class="btn primary" type="submit">Registrar fechamento ${icon('check')}</button></div></form>`);}
function download(content,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000);}
async function handleAction(action,el){const id=el?.dataset.id;
 if(action==='plan-period'){planPeriod=el.dataset.period;render();return;}
 if(action==='launch-tab'){launchTab=el.dataset.tab;render();return;}
 if(action==='launch-export'){const rows=el.dataset.kind==='profiles'?LAUNCH_DATA.profiles:LAUNCH_DATA.creators;const fields=el.dataset.kind==='profiles'?['id','alias','city','state','region','occupation','context','pains','desires','objections','journey','test_input','improvement','synthetic']:['id','name','niche','priority','official_url','fit_hypothesis','outreach_angle','commercial_status','metrics_status'];const cell=value=>'\"'+String(Array.isArray(value)?value.join(' | '):value??'').replace(/^(?=[\s\u0000-\u001f]*[=+\-@])/,'\'').replaceAll('\"','\"\"')+'\"';const csv=[fields,...rows.map(row=>fields.map(field=>row[field]))].map(row=>row.map(cell).join(';')).join('\r\n');download('\ufeff'+csv,'aya-50-'+el.dataset.kind+'.csv','text/csv;charset=utf-8');return;}
 if(action==='creator-tab'){creatorTab=el.dataset.tab;render();return;}
 if(action==='creator-refresh'){creatorRequested=true;await loadCreator();return;}
 if(action==='creator-copy-link'){await copyVisible(document.querySelector('#creator-link')?.value||'');return;}
 if(action==='creator-copy-material'||action==='creator-download-material'){const material=CREATOR_MATERIALS.find(m=>m.id===id);if(!material)return;const text=material.title+'\n\n'+material.body+(material.caption?'\n\nLegenda sugerida\n'+material.caption:'');if(action==='creator-copy-material')await copyVisible(text);else download(text,'aya-'+id+'.txt','text/plain;charset=utf-8');return;}
 if(presentationOnly&&['creator-approve','creator-suspend','creator-payout','creator-settle','creator-cancel-payout','checkout','billing-portal'].includes(action)){toast('Esta apresentação não cria contas, cobranças ou pagamentos.');return;}
 if(demo&&['creator-approve','creator-suspend','creator-payout','creator-settle','creator-cancel-payout','checkout','billing-portal'].includes(action)){toast('Saia da demonstração para usar seu acesso real.');return;}
 if(action==='creator-approve'||action==='creator-suspend'||action==='creator-payout'||action==='creator-cancel-payout'){try{await portalApi(action==='creator-payout'?'/api/affiliate/payout':'/api/affiliate/admin',action==='creator-payout'?{}:action==='creator-cancel-payout'?{action:'cancel-payout',payoutId:id}:{action:action==='creator-approve'?'approve':'suspend',creatorId:id,mode:el.dataset.mode});await loadCreator();toast(action==='creator-payout'?'Pedido enviado para conferência.':'Cadastro atualizado.');}catch(error){toast(error.message);}return;}
 if(action==='creator-settle'){showDialog(`<h2>Registrar um pagamento realizado.</h2><p>Este formulário registra um pagamento feito pela operação. Ele não transfere dinheiro.</p><form id="creator-settlement" data-id="${e(id)}"><label>Referência do comprovante</label><input name="reference" required minlength="4" maxlength="160" placeholder="Referência do pagamento conferido"><div class="dialog-footer"><button class="btn outline" type="button" data-dialog="close">Voltar</button><button class="btn primary" type="submit">Registrar pagamento</button></div></form>`);return;}
 if(action==='new-routine'||action==='ritual-preset'){routineDialog(RITUAL_PRESETS.find(p=>p.id===id));return;}
 if(action==='toggle-routine'){await mutate(s=>{s.routineChecks=s.routineChecks||[];const index=s.routineChecks.findIndex(c=>c.routineId===id&&c.date===currentDay());if(index>=0)s.routineChecks.splice(index,1);else s.routineChecks.push({id:uid(),routineId:id,date:currentDay(),createdAt:new Date().toISOString()});activity(s,'Um passo do ritual foi atualizado por você.');});return;}
 if(action==='pause-routine'){await mutate(s=>{const r=s.routines?.find(r=>r.id===id);if(r)r.enabled=!r.enabled;});return;}
 if(action==='delete-routine'){if(!confirm('Excluir este ritual?'))return;await mutate(s=>{s.routines=s.routines.filter(r=>r.id!==id);s.routineChecks=s.routineChecks.filter(c=>c.routineId!==id);});return;}
 if(action==='checkout'||action==='billing-portal'){if(!loggedIn){window.location.href='#presentation';return;}try{const result=await portalApi(action==='checkout'?'/api/billing/checkout':'/api/billing/portal',action==='checkout'?{plan:el.dataset.plan}:{});window.location.href=result.url;}catch(error){toast(error.message);}return;}

 if(action==='journey'){const role=el.dataset.role;if(!JOURNEYS[role])return;setJourneyRoute(role);if(role==='user'){startPersonalPreview();return;}portalRole=role;portalTab='overview';view=review.roleProfiles[role]?'portal':'role-onboarding';render();window.scrollTo(0,0);return;}
 if(action==='portal-tab'){if(!JOURNEYS[portalRole].tabs.some(t=>t[0]===el.dataset.tab))return;portalTab=el.dataset.tab;setJourneyRoute(portalRole,portalTab);view='portal';render();window.scrollTo(0,0);return;}
 if(action==='review-person'){showDialog(`<h2>Uma pessoa para sua equipe.</h2><p>Teste a organização de um perfil. Nenhum convite será enviado.</p><form id="review-person"><label for="review-person-name">Nome de exemplo</label><input id="review-person-name" name="name" maxlength="60" required><label for="review-person-channel">Perfil público</label><input id="review-person-channel" name="channel" placeholder="@seuperfil" pattern="@[a-zA-Z0-9._]{1,30}" required><div class="dialog-footer"><button class="btn outline" type="button" data-dialog="close">Voltar</button><button class="btn primary" type="submit">Adicionar ao teste</button></div></form>`);return;}
 if(action==='review-person-ready'){const person=review.people.find(p=>p.id===el.dataset.id);if(!person)return;person.status=person.status==='ready'?'draft':'ready';saveReview();render();toast('Etapa atualizada no seu teste.');return;}
 if(action==='review-check'){const id=el.dataset.id;if(!new RegExp('^'+portalRole+'-[0-4]$').test(id))return;review.checklist=review.checklist.includes(id)?review.checklist.filter(x=>x!==id):[...review.checklist,id];saveReview();render();return;}
 if(action==='review-copy'){try{await navigator.clipboard.writeText(root.querySelector('#review-link').value);toast('Exemplo copiado. Ele ainda não recebe cadastros.');}catch{root.querySelector('#review-link')?.select();toast('Selecione e copie o exemplo.');}return;}
 if(action==='review-download'){const m=REVIEW_MATERIALS.find(m=>m.id===el.dataset.id);if(m)download('AYAH · '+m.title+'\n\n'+m.text,'ayah-'+m.id+'.txt','text/plain;charset=utf-8');return;}
 if(action==='onboarding-next'){const fields=[...root.querySelectorAll(`[data-step="${onboardingStep}"] input,[data-step="${onboardingStep}"] select`)];if(fields.some(f=>!f.reportValidity()))return;onboardingStep=Math.min(2,onboardingStep+1);showOnboardingStep();return;}
 if(action==='onboarding-back'){onboardingStep=Math.max(0,onboardingStep-1);showOnboardingStep();return;}
 if(action==='day-mode'){if(!DAY_MODES[el.dataset.mode])return;await mutate(s=>{s.settings.dayMode=el.dataset.mode;s.settings.dayModeDate=currentDay();activity(s,'Seu ritmo de hoje foi atualizado.');});return;}
 if(action==='food-budget'){showDialog(`<h2>Quanto cabe neste mês?</h2><p>Um combinado para comer fora, baseado nos gastos que você registrar.</p><form id="food-budget"><label for="budget-value">Limite em reais</label><input id="budget-value" name="amount" type="number" step="0.01" min="1" max="999999" value="${state.settings.foodBudget||500}" required><div class="dialog-footer"><button type="button" class="btn outline" data-dialog="close">Voltar</button><button class="btn primary" type="submit">Salvar meu combinado</button></div></form>`);return;}
 if(action==='purchase-pause'){showDialog(`<h2>Essa compra pode esperar?</h2><p>Guarde a ideia. Depois, você decide com mais calma.</p><form id="purchase-pause"><label for="purchase-name">O que você está pensando em comprar?</label><input id="purchase-name" name="title" maxlength="450" required><label for="purchase-hours">Quando você quer pensar nisso de novo?</label><select id="purchase-hours" name="hours"><option value="24">Daqui a 24 horas</option><option value="48">Daqui a 48 horas</option></select><div class="dialog-footer"><button type="button" class="btn outline" data-dialog="close">Voltar</button><button class="btn primary" type="submit">Criar uma pausa</button></div></form>`);return;}
 if(action==='focus-start'){focusEnds=Date.now()+5*60000;showDialog(`<h2>Só cinco minutos.</h2><p>Escolha uma pequena tarefa e dê o primeiro passo. Você pode parar quando precisar.</p><div class="focus-clock" id="focus-clock" role="timer">05:00</div><small>O tempo não marca nenhuma tarefa como concluída.</small><div class="dialog-footer"><button class="btn outline" data-dialog="close">Encerrar esta pausa</button></div>`);clearInterval(focusTimer);focusTimer=setInterval(()=>{const el=document.querySelector('#focus-clock');if(!el||!dialog.open){clearInterval(focusTimer);return;}const remaining=Math.max(0,Math.ceil((focusEnds-Date.now())/1000));el.textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');if(!remaining){clearInterval(focusTimer);toast('Cinco minutos. Você pode continuar ou fazer uma pausa.');}},1000);return;}
 if(action==='site-menu'){showDialog(`<h2>Explore a AYAH.</h2><p>O produto e a apresentação, no mesmo lugar.</p><div class="site-menu-grid">${nav.filter(([id])=>!['partner','research','launch','design','ecosystem','affiliate'].includes(id)).map(([id,i,label])=>`<button class="btn outline" data-dialog="navigate" data-view="${id}">${icon(i)}${e(label)} ${icon('arrow')}</button>`).join('')}</div><div class="dialog-footer"><button class="btn outline" data-dialog="close">Fechar</button></div>`);return;}
 if(action==='compose'){if(!state.onboarded){view='onboarding';render();return;}view='today';render();const field=root.querySelector('[name=capture]');field?.scrollIntoView?.({behavior:'smooth',block:'center'});field?.focus();return;}
 if(action==='demo'){if(!demo)realState=structuredClone(state);demo=true;state=demoState();view=el?.dataset?.startView==='rhythm'?'rhythm':'today';render();return;}
 if(action==='leave-demo'&&(presentationOnly||!loggedIn)){startPersonalPreview({empty:true});return;}if(action==='leave-demo'){demo=false;state=realState||emptyState();view=state.onboarded?'today':'onboarding';render();return;}
 if(action==='start'){if(!loggedIn||presentationOnly){startPersonalPreview();return;}if(demo){state=realState||emptyState();demo=false;}view=state.onboarded?'today':'onboarding';render();return;}if(action==='welcome'){view='presentation';render();return;}
 if(action==='ds-demo'){toast('Componente compartilhado. O comportamento é definido no controlador global.');return;}
 if(action==='copy-token'){const value=getComputedStyle(document.documentElement).getPropertyValue(el.dataset.token).trim();if(!navigator.clipboard?.writeText){toast(el.dataset.token+' · '+value);return;}try{await navigator.clipboard.writeText(el.dataset.token+': '+value);toast('Token copiado.');}catch{toast(el.dataset.token+' · '+value);}return;}
 if(action==='menu'){setMenu(!menuOpen);return;}if(action==='close-menu'){setMenu(false);return;}
 if(action==='new-task'||action==='edit-task'){taskDialog(id);return;}
 if(action==='new-memory'||action==='edit-memory'){memoryDialog(id);return;}
 if(action==='new-expense'||action==='edit-expense'){expenseDialog(id);return;}
 if(action==='toggle-task'){const target=state.tasks.find(t=>t.id===id);if(target?.status==='done'&&target.priority&&state.tasks.filter(t=>t.priority&&t.status!=='done').length>=3){toast('Antes de reabrir, ajuste suas três prioridades em aberto.');return;}await mutate(s=>{const t=s.tasks.find(t=>t.id===id);if(t){t.status=t.status==='done'?'pending':'done';t.completedAt=t.status==='done'?new Date().toISOString():null;activity(s,t.status==='done'?'Compromisso concluído por você.':'Compromisso reaberto por você.');}});return;}
 if(action==='delete-memory'||action==='delete-water'){if(!confirm('Excluir este registro?'))return;const field=action==='delete-memory'?'memories':'water';await mutate(s=>{s[field]=s[field].filter(t=>t.id!==id);activity(s,'Registro excluído por você.');});return;}
 if(action==='water'){await mutate(s=>{s.water.push({id:uid(),amount:250,createdAt:new Date().toISOString()});activity(s,'250 ml de água registrados.');});return;}
 if(action==='water-custom'){showDialog('<h2>Uma pausa para água.</h2><form id="water-form"><label>Quantidade em ml</label><input name="amount" type="number" value="250" min="0.01" max="6000" step="0.01" required><div class="dialog-footer"><button class="btn outline" type="button" data-dialog="close">Cancelar</button><button class="btn primary" type="submit">Registrar</button></div></form>');return;}
 if(action==='closing'){closingDialog();return;}
 if(action==='example'){const ta=document.querySelector('[name=capture]');ta.value=el.dataset.text;ta.focus();return;}
 if(action==='capture-text'){previewCapture(el.dataset.text);return;}
 if(action==='choose-priorities'){const open=state.tasks.filter(t=>t.status!=='done');showDialog(`<h2>O que importa hoje?</h2><p>Escolha até três compromissos para dar atenção.</p><form id="priorities-form">${open.length?open.map(t=>`<label class="checkin-choice toggle"><input type="checkbox" name="task" value="${e(t.id)}" ${t.priority?'checked':''}>${e(t.title)}</label>`).join(''):'<div class="notice">Adicione seu primeiro compromisso para escolher prioridades.</div>'}<div class="dialog-footer"><button class="btn outline" type="button" data-dialog="close">Voltar</button>${open.length?'<button class="btn primary" type="submit">Salvar minhas prioridades</button>':'<button class="btn primary" type="button" data-dialog="new-task">Adicionar compromisso</button>'}</div></form>`);return;}
 if(action==='plan'){if(!PLANS.find(x=>x.id===el.dataset.plan&&x.canRegisterInterest))return toast('Esta oferta está suspensa.');if(!state.onboarded){view='onboarding';render();return;}if(await mutate(s=>{s.planInterest=el.dataset.plan;activity(s,'Interesse em plano registrado, sem cobrança.');}))toast('Interesse registrado. Nenhuma cobrança foi realizada.');return;}
 if(action==='export'){download(JSON.stringify(state,null,2),'aya-meus-dados.json','application/json');return;}
 if(action==='export-expenses'){const cell=v=>'"'+String(v).replace(/^(?=[\s\u0000-\u001f]*[=+\-@])/,'\'').replaceAll('"','""')+'"';const lines=[['Descrição','Categoria','Valor','Moeda','Tipo','Data'],...state.expenses.map(x=>[x.title,x.category,x.amount,x.currency,x.direction,x.createdAt])].map(x=>x.map(cell).join(';')).join('\r\n');download('\ufeff'+lines,'aya-meus-registros.csv','text/csv;charset=utf-8');return;}
 if(action==='notifications'){if(!('Notification'in window))return toast('Este navegador não oferece notificações.');const p=await Notification.requestPermission();toast(p==='granted'?'Você receberá lembretes enquanto a página estiver aberta.':'Permissão não concedida. Os lembretes continuam visíveis no painel.');return;}
 if(action==='reminders'){view='agenda';filter='pending';render();return;}
 if(action==='voice'){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return toast('Voz não disponível neste navegador. Você pode digitar a mensagem.');if(voice){voice.stop();return;}voice=new SR();voice.lang='pt-BR';voice.interimResults=false;voice.continuous=false;const button=document.querySelector('.voice');button?.classList.add('recording');voice.onresult=event=>{const ta=document.querySelector('[name=capture]');if(ta)ta.value=(ta.value+' '+event.results[0][0].transcript).trim();toast('Mensagem transcrita. Confira antes de organizar.');};voice.onerror=()=>toast('Não foi possível captar a voz. Verifique a permissão do microfone.');voice.onend=()=>{voice=null;document.querySelector('.voice')?.classList.remove('recording');};try{voice.start();}catch{voice=null;button?.classList.remove('recording');toast('Não foi possível iniciar o microfone. Você pode digitar a mensagem.');}}
}
root.addEventListener('click',event=>{const el=event.target.closest('button,[data-action]');if(!el)return;if(el.dataset.view){view=el.dataset.view;if(window.history&&window.location)window.history.replaceState(null,'','#'+view);search='';filter='all';render();window.scrollTo(0,0);root.querySelector('#main-content')?.focus();}else if(el.dataset.filter){filter=el.dataset.filter;render();}else if(el.dataset.action)handleAction(el.dataset.action,el);});
root.addEventListener('change',event=>{if(event.target.id==='launch-region'){launchRegion=event.target.value;render();return;}if(event.target.id==='launch-priority'){launchPriority=event.target.value;render();return;}if(event.target.id==='creator-campaign'){const field=document.querySelector('#creator-link');if(field&&creatorData?.profile?.link)field.value=creatorData.profile.link+'?campaign='+encodeURIComponent(event.target.value);}});
root.addEventListener('input',event=>{if(event.target.closest?.('.cost-controls')){calcCosts(root.querySelector('.research'));return;}event.target.setCustomValidity?.('');if(event.target.id==='memory-search'){const position=event.target.selectionStart;search=event.target.value;render();const input=document.querySelector('#memory-search');input.focus();input.setSelectionRange(position,position);}});
root.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;if(!validForm(form))return;const f=new FormData(form);if(form.id==='journey-onboarding'){const role=form.dataset.role;if(!['ceo','agent','influencer'].includes(role))return;review.roleProfiles[role]={name:String(f.get('name')).trim(),organization:String(f.get('organization')).trim(),goal:String(f.get('goal'))};if(role==='ceo')review.organization=review.roleProfiles[role].organization;saveReview();portalRole=role;portalTab='overview';view='portal';render();toast('Seu espaço de apresentação está pronto.');return;}if(form.id==='creator-application'){if(demo){toast('Saia da demonstração para enviar seu cadastro real.');return;}try{await portalApi('/api/affiliate/apply',{name:String(f.get('name')).trim(),channel:String(f.get('channel')).trim(),code:String(f.get('code')).trim(),acceptedTerms:f.has('terms')?AFFILIATE_POLICY.version:null});await loadCreator();toast('Cadastro recebido. A aprovação aparecerá no seu portal.');}catch(error){toast(error.message);}return;}if(form.id==='capture'){previewCapture(f.get('capture'));return;}if(form.id==='onboarding'){if(await mutate(s=>{s.name=String(f.get('name')).trim();s.onboarded=true;s.settings.closingTime=f.get('closingTime');s.settings.timezone=f.get('timezone');s.settings.conversationStyle=f.get('conversationStyle')||'warm';s.memories.push({id:uid(),title:String(f.get('firstMemory')).trim(),source:'Primeira memória informada no onboarding.',createdAt:new Date().toISOString()});activity(s,'Sua primeira memória foi guardada.');})){view='today';render();toast('Seu espaço está pronto para começar.');}return;}if(form.id==='settings'){if(await mutate(s=>{s.name=String(f.get('name')).trim();s.settings={...s.settings,waterGoal:Number(f.get('waterGoal')),closingTime:f.get('closingTime'),timezone:f.get('timezone'),conversationStyle:f.get('conversationStyle')||'warm',quietStart:f.get('quietStart'),quietEnd:f.get('quietEnd'),followUp:f.has('followUp')};activity(s,'Preferências atualizadas.');}))toast('Seu ritmo foi atualizado.');}});
dialog.addEventListener('click',async event=>{const b=event.target.closest('button[data-dialog]');if(!b)return;const action=b.dataset.dialog,id=b.dataset.id;if(action==='navigate'){view=b.dataset.view;closeDialog();render();window.scrollTo(0,0);return;}if(action==='close'){closeDialog();return;}if(action==='reschedule'||action==='new-task'){closeDialog();taskDialog(id);return;}if(action==='delete-task'||action==='delete-expense'){if(!confirm('Excluir este registro?'))return;const field=action==='delete-task'?'tasks':'expenses';if(await mutate(s=>{s[field]=s[field].filter(x=>x.id!==id);activity(s,'Registro excluído por você.');}))closeDialog();}});
dialog.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;if(!validForm(form))return;const f=new FormData(form),id=form.dataset.id;let fn;
 if(form.id==='review-person'){try{review=addReviewPerson(review,{name:f.get('name'),channel:f.get('channel')});saveReview();closeDialog();render();toast('Perfil incluído apenas na lista de teste.');}catch(error){toast(error.message);}return;}
 if(form.id==='creator-settlement'){try{await portalApi('/api/affiliate/admin',{action:'settle',payoutId:form.dataset.id,reference:String(f.get('reference')).trim()});closeDialog();await loadCreator();toast('Pagamento registrado pela operação.');}catch(error){toast(error.message);}return;}
 if(form.id==='food-budget'){fn=s=>{s.settings.foodBudget=Number(f.get('amount'));activity(s,'Limite para alimentação atualizado.');};}
 else if(form.id==='purchase-pause'){const hours=Number(f.get('hours'));if(![24,48].includes(hours))return;const due=new Date(Date.now()+hours*3600000),zone=timezone(),date=localDay(due,zone),time=new Intl.DateTimeFormat('pt-BR',{timeZone:zone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(due);fn=s=>{s.tasks.push({id:uid(),title:'Rever com calma · '+String(f.get('title')).trim(),date,time,due:dateTimeToISO(date,time,zone),timezone:zone,status:'pending',priority:false,source:'Pausa de '+hours+' horas escolhida por você.',createdAt:new Date().toISOString()});activity(s,'Uma pausa antes da compra foi criada.');};}
 else if(form.id==='routine-form'){const weekdays=f.getAll('weekday').map(Number);if(!weekdays.length){toast('Escolha ao menos um dia.');return;}fn=s=>{s.routines=s.routines||[];if(s.routines.length>=30)throw Error('Você já tem 30 rituais. Ajuste os que já criou.');s.routines.push({id:uid(),title:String(f.get('title')).trim(),time:f.get('time'),weekdays,enabled:true,createdAt:new Date().toISOString()});activity(s,'Seu ritual foi criado.');};}
 else if(form.id==='preview-capture'){
  const items=pending.map((x,i)=>{const out={...x,title:String(f.get(`title-${i}`)).trim(),reviewRequired:false};if(x.kind==='task'){out.date=f.get(`date-${i}`);out.time=f.get(`time-${i}`);out.timezone=x.timezone||timezone();out.due=dateTimeToISO(out.date,out.time,out.timezone);out.priority=f.has(`priority-${i}`);}if(x.kind==='expense'||x.kind==='water')out.amount=Number(f.get(`amount-${i}`));if(x.kind==='expense'){out.currency=f.get(`currency-${i}`);out.category=f.get(`category-${i}`);}return out;});
  if(items.some(x=>x.kind==='task'&&!x.due)){toast('Confira a data e o horário antes de salvar.');return;}
  if(items.filter(x=>x.kind==='task'&&x.priority).length+state.tasks.filter(x=>x.priority&&x.status!=='done').length>3){toast('Você já tem prioridades em aberto. Ajuste a seleção para manter até três.');return;}
  fn=s=>{items.forEach(x=>{s[{task:'tasks',memory:'memories',expense:'expenses',water:'water'}[x.kind]].push(x);activity(s,'Registro confirmado por você.');});};
 }else if(form.id==='task-form'){
  const oldTask=state.tasks.find(t=>t.id===id),x={title:String(f.get('title')).trim(),date:f.get('date'),time:f.get('time'),timezone:f.get('timezone')||(oldTask?oldTask.timezone||DEFAULT_TIMEZONE:timezone()),priority:f.has('priority')};x.due=dateTimeToISO(x.date,x.time,x.timezone);
  if(!x.due){toast('Confira a data e o horário antes de salvar.');return;}
  if(x.priority&&oldTask?.status!=='done'&&state.tasks.filter(t=>t.priority&&t.status!=='done'&&t.id!==id).length>=3){toast('Escolha até três prioridades em aberto.');return;}
  fn=s=>{const old=s.tasks.find(t=>t.id===id);if(old)Object.assign(old,x,{notifiedAt:null});else s.tasks.push({...x,id:uid(),status:'pending',source:'Você registrou pelo formulário.',createdAt:new Date().toISOString()});activity(s,old?'Compromisso atualizado por você.':'Compromisso registrado por você.');};
 }else if(form.id==='memory-form'){const title=String(f.get('title')).trim();fn=s=>{const old=s.memories.find(x=>x.id===id);if(old){old.title=title;old.updatedAt=new Date().toISOString();}else s.memories.push({id:uid(),title,source:'Você registrou pelo formulário.',createdAt:new Date().toISOString()});activity(s,'Informação guardada na memória.');};
 }else if(form.id==='expense-form'){const x={title:String(f.get('title')).trim(),amount:Number(f.get('amount')),currency:f.get('currency'),category:f.get('category'),direction:f.get('direction')};fn=s=>{const old=s.expenses.find(t=>t.id===id);if(old)Object.assign(old,x);else s.expenses.push({...x,id:uid(),source:'Você registrou pelo formulário.',createdAt:new Date().toISOString()});activity(s,'Registro financeiro confirmado.');};
 }else if(form.id==='water-form'){const amount=Number(f.get('amount'));fn=s=>{s.water.push({id:uid(),amount,createdAt:new Date().toISOString()});activity(s,`${amount} ml de água registrados.`);};
 }else if(form.id==='priorities-form'){const ids=f.getAll('task');if(ids.length>3)return toast('Escolha até três prioridades.');fn=s=>{s.tasks.forEach(t=>{if(t.status!=='done')t.priority=ids.includes(t.id);});activity(s,'Prioridades escolhidas por você.');};
 }else if(form.id==='closing-form'){if(state.closings.some(x=>localDay(new Date(x.createdAt),timezone())===currentDay()))return toast('Você já registrou o fechamento de hoje.');fn=s=>{const d=dailyStats(s,currentDay(),timezone());s.closings.push({id:uid(),createdAt:new Date().toISOString(),done:d.done,total:d.tasks,note:String(f.get('note')).trim()});activity(s,'Fechamento do dia registrado.');};}
 if(fn&&await mutate(fn)){closeDialog();toast(conversation().saved);}
});
setInterval(async()=>{if(demo||busy||!state.onboarded||dialog.open)return;const time=new Intl.DateTimeFormat('pt-BR',{timeZone:timezone(),hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());const a=state.settings.quietStart,b=state.settings.quietEnd;if(a>b?(time>=a||time<b):(time>=a&&time<b))return;if(time>=state.settings.closingTime&&!closingNotified.has(currentDay())&&!state.closings.some(c=>localDay(new Date(c.createdAt),timezone())===currentDay())){closingNotified.add(currentDay());toast('Seu fechamento está pronto. Veja o que fica para amanhã em Minha semana.');}const due=state.tasks.find(t=>t.status!=='done'&&t.due&&new Date(t.due)<=new Date()&&!t.notifiedAt);if(!due){const day=currentDay(),weekday=new Date(day+'T12:00:00Z').getUTCDay(),current=Number(time.slice(0,2))*60+Number(time.slice(3));const r=(state.routines||[]).find(r=>{const target=Number(r.time.slice(0,2))*60+Number(r.time.slice(3));return r.enabled&&r.weekdays.includes(weekday)&&current>=target&&current-target<=15&&!routineNotified.has(r.id+day)&&!state.routineChecks?.some(c=>c.routineId===r.id&&c.date===day);});if(r){routineNotified.add(r.id+day);toast('Seu ritual · '+r.title);if('Notification'in window&&Notification.permission==='granted')new Notification('AYAH · Seu ritual',{body:r.title});}}if(due){const title=due.title;if(await mutate(s=>{const t=s.tasks.find(x=>x.id===due.id);t.notifiedAt=new Date().toISOString();activity(s,'Lembrete exibido no navegador.');})){toast('Lembrete · '+title);if('Notification'in window&&Notification.permission==='granted')new Notification('AYAH · Um compromisso seu',{body:title});}}},30000);
